// Catálogo oficial das 15 personas padrão pt-BR da Segunda Mente (seed v6).

use super::personas::{extract_comment_policy_from_text, strip_comment_policy_from_text, PersonaProfile};

pub const CURRENT_SEED_VERSION: u32 = 6;

#[allow(clippy::too_many_arguments)]
fn build_default(
    id: &str,
    name: &str,
    tags: &[&str],
    avatar: &str,
    raw_persona: &str,
    style_guide: &str,
    example_dialogue: &str,
    first_message: &str,
    post_history_instructions: &str,
    pkm_interest_filter: &str,
    color: &str,
    is_primary_companion: bool,
) -> PersonaProfile {
    let base = strip_comment_policy_from_text(raw_persona);
    let identity = if style_guide.trim().is_empty() {
        base
    } else if base.is_empty() {
        format!("## Voice\n{}", style_guide.trim())
    } else {
        format!("{base}\n\n## Voice\n{}", style_guide.trim())
    };
    let rules = extract_comment_policy_from_text(raw_persona).unwrap_or_default();
    let persona = if style_guide.trim().is_empty() {
        raw_persona.trim().to_string()
    } else {
        format!("{}\n\n## Voice\n{}", raw_persona.trim(), style_guide.trim())
    };

    PersonaProfile {
        id: id.to_string(),
        name: name.to_string(),
        role: None,
        identity,
        user_profile: String::new(),
        rules,
        persona,
        system_prompt_override: None,
        post_history_instructions: Some(post_history_instructions.to_string()),
        mes_example: Some(example_dialogue.to_string()),
        tags: tags.iter().map(|s| (*s).to_string()).collect(),
        interest_filter: Some(pkm_interest_filter.to_string()),
        avatar: Some(avatar.to_string()),
        first_message: Some(first_message.to_string()),
        is_primary_companion,
        enabled: true,
        color: color.to_string(),
    }
}

pub fn default_color_for_id(id: &str) -> Option<&'static str> {
    match id {
        "socio_tecnico" => Some("#6C5CE7"),
        "revisor_chato" => Some("#E17055"),
        "cobrador_prazo" => Some("#D63031"),
        "memoria_projeto" => Some("#0984E3"),
        "advogado_diabo" => Some("#E84393"),
        "facilitador_execucao" => Some("#00B894"),
        "guardiao_energia" => Some("#00CEC9"),
        "observador_progresso" => Some("#2ECC71"),
        "escuta_atenta" => Some("#A29BFE"),
        "calmo_crise" => Some("#00A8FF"),
        "provocador_criativo" => Some("#F39C12"),
        "tradutor" => Some("#1ABC9C"),
        "amigo_bar" => Some("#FDCB6E"),
        "financas_burocracia" => Some("#16A085"),
        "curador" => Some("#9B59B6"),
        _ => None,
    }
}

